from pathlib import Path

p = Path("src/deps.ts")
s = p.read_text()

needle = 'import { type FilePath } from "@vrtmrz/livesync-commonlib/compat/common/types";\n'
insert = '''import { type FilePath } from "@vrtmrz/livesync-commonlib/compat/common/types";\nimport { setFetch } from "@vrtmrz/livesync-commonlib/compat/common/coreEnvFunctions";\nimport { Platform as ObsidianPlatform, requestUrl as obsidianRequestUrl } from "obsidian";\n\nconst browserFetch = globalThis.fetch.bind(globalThis);\nconst FAST_FETCH_REQUEST_TIMEOUT_MS = 7_000;\nconst FAST_FETCH_REQUEST_ATTEMPTS = 1;\nconst SYNC_PARAMS_PATH = "/_local/obsidian_livesync_sync_parameters";\n\nfunction errorText(error: unknown): string {\n    return error instanceof Error ? error.message : String(error);\n}\n\nasync function requestUrlSingleAttempt(\n    url: string,\n    method: string,\n    headers: Record<string, string>,\n    body: string | ArrayBuffer | undefined\n) {\n    console.log(`[FastFetchDebug] requestUrl transport begin: ${url} attempt=1/${FAST_FETCH_REQUEST_ATTEMPTS}`);\n    try {\n        const timeout = new Promise<never>((_, reject) => {\n            setTimeout(\n                () => reject(new Error(`requestUrl timed out after ${FAST_FETCH_REQUEST_TIMEOUT_MS}ms`)),\n                FAST_FETCH_REQUEST_TIMEOUT_MS\n            );\n        });\n        const request = obsidianRequestUrl({\n            url,\n            method,\n            headers,\n            body,\n            throw: false,\n        });\n        const nativeResponse = await Promise.race([request, timeout]);\n        console.log(`[FastFetchDebug] requestUrl transport status: ${nativeResponse.status} attempt=1/1`);\n        return nativeResponse;\n    } catch (error) {\n        console.log(`[FastFetchDebug] requestUrl transport error: attempt=1/1 ${errorText(error)}`);\n        throw error instanceof Error ? error : new Error(errorText(error));\n    }\n}\n\nif (ObsidianPlatform.isMobileApp) {\n    setFetch(async (input: RequestInfo | URL, init?: RequestInit): Promise<Response> => {\n        const url = typeof input === "string" ? input : input instanceof URL ? input.toString() : input.url;\n        const isFastFetchChanges = url.includes("/_changes?") && url.includes("feed=normal");\n        const isSyncParams = url.includes(SYNC_PARAMS_PATH);\n        if (!isFastFetchChanges && !isSyncParams) {\n            return browserFetch(input, init);\n        }\n\n        if (isSyncParams) {\n            console.log(`[FastFetchDebug] requestUrl native sync-params transport: ${url}`);\n        }\n\n        const headers: Record<string, string> = {};\n        new Headers(init?.headers).forEach((value, key) => {\n            headers[key] = value;\n        });\n\n        let body: string | ArrayBuffer | undefined;\n        if (typeof init?.body === "string") {\n            body = init.body;\n        } else if (init?.body instanceof ArrayBuffer) {\n            body = init.body;\n        } else if (ArrayBuffer.isView(init?.body)) {\n            const view = init.body;\n            body = view.buffer.slice(view.byteOffset, view.byteOffset + view.byteLength);\n        } else if (init?.body != null) {\n            return browserFetch(input, init);\n        }\n\n        const nativeResponse = await requestUrlSingleAttempt(\n            url,\n            init?.method ?? "GET",\n            headers,\n            body\n        );\n\n        const responseHeaders = new Headers();\n        for (const [key, value] of Object.entries(nativeResponse.headers)) {\n            if (typeof value === "string") responseHeaders.set(key, value);\n        }\n\n        return new Response(nativeResponse.arrayBuffer, {\n            status: nativeResponse.status,\n            headers: responseHeaders,\n        });\n    });\n}\n'''

if needle not in s:
    raise SystemExit("deps.ts import anchor not found")

s = s.replace(needle, insert, 1)
p.write_text(s)
print("Mobile requestUrl Fast Fetch + sync-params transport single-attempt 7s patch applied")
